def cols(p):
    b,d,a,q,r,s,k=p
    return np.column_stack([np.tanh(b*t),np.tanh(d*t)*P**3, np.abs(t)**a*P**q, P**r*np.exp(-k*t)*np.abs(t)**s, np.ones_like(t)])
def resid(p):
    A=cols(p)
    c,*_=np.linalg.lstsq(A,y,rcond=None)
    return np.nan_to_num(A@c-y,nan=1e3,posinf=1e3,neginf=-1e3)
